def _name_map(c, entity):
    """Ref_Key -> Description. Стійко до відсутності довідника в публікації OData:
    якщо об'єкт не опубліковано (напр. 404) — повертаємо {} і йдемо далі
    (назви лишаться порожні, але цифри й пайплайн не ламаються)."""
    try:
        return {r["Ref_Key"]: (r.get("Description") or "")
                for r in c.list(entity, select=["Ref_Key", "Description"])}
    except Exception as e:
        print(f"  ⚠ довідник {entity} недоступний ({type(e).__name__}) — назви з нього будуть порожні")
        return {}


